export function evaluateG2U2L04(obs: G2Observations): G2TaskState {
  const flights = obs.frameRuns.map(flightSummary).filter((f): f is FlightSummary => !!f && f.turn > 0)
  const firstOpen = flights.findIndex(f => f.turn % 360 !== 0)
  const line = obs.lastSaid['蝴蝶']
  return {
    practiceA: flights.some(f => f.closed),
    practiceB: flights.some(f => f.closed && f.turn === 720),
    debug: firstOpen >= 0 && flights.slice(firstOpen + 1).some(f => f.closed),
    create: !!line && line !== L10_FLY_LINE && flights.some(f => f.closed && f.frames >= 10),
  }
}

type CycleRun = G2Observations['cycleRuns'][number]
const spokeOn = (run: CycleRun, target: string, backdrop: string) => run.speech.some(s => s.target === target && s.backdrop === backdrop)
const longPhases = (run: CycleRun) => run.switches >= 2 && run.avgMs !== null && run.avgMs >= L08_LONG_PHASE_MS
const owlOnlyAtNight = (run: CycleRun) => spokeOn(run, '猫头鹰', '夜晚') && !spokeOn(run, '猫头鹰', '白天')

export function evaluateG2U2L02(obs: G2Observations): G2TaskState {
  const runs = obs.cycleRuns
  const firstDayHoot = runs.findIndex(r => spokeOn(r, '猫头鹰', '白天'))
  const line = obs.lastSaid['猫头鹰']
  return {
    practiceA: runs.some(r => longPhases(r) && r.finished && r.stopped),
    practiceB: runs.some(r => spokeOn(r, '小橘猫', '白天')),
    debug: firstDayHoot >= 0 && runs.slice(firstDayHoot + 1).some(owlOnlyAtNight),
    create: !!line && line !== L08_OWL_LINE && runs.some(r => owlOnlyAtNight(r) && longPhases(r) && spokeOn(r, '小橘猫', '白天')),
  }
}

type FrameRun = G2Observations['frameRuns'][number]
const catFrames = (run: FrameRun) => run.frames['小橘猫']
const fullCycle = (run: FrameRun) => { const f = catFrames(run); return !!f && f.count >= 4 && f.end === '走路1' }
const visible = (run: FrameRun) => { const f = catFrames(run); return !!f && f.avgMs !== null && f.avgMs >= L07_VISIBLE_MS }
const tooFast = (run: FrameRun) => { const f = catFrames(run); return !!f && f.avgMs !== null && f.avgMs < L07_TOO_FAST_MS }

export function evaluateG2U2L01(obs: G2Observations): G2TaskState {
  const runs = obs.frameRuns.filter(r => !!catFrames(r))
  const firstFast = runs.findIndex(tooFast)
  const line = obs.lastSaid['小橘猫']
  return {
    practiceA: runs.some(fullCycle),
    practiceB: runs.some(r => atDoor(r.positions['小橘猫'])),
    debug: firstFast >= 0 && runs.slice(firstFast + 1).some(visible),
    create: !!line && line !== L07_CAT_LINE && runs.some(r => fullCycle(r) && visible(r) && atDoor(r.positions['小橘猫'])),
  }
}

export function observedPredictionG2U2(id: string, obs: G2Observations): string | null {
  if (id === g2u2L01.id) {
    const first = obs.frameRuns.find(r => catFrames(r)?.avgMs !== null && catFrames(r)?.avgMs !== undefined)
    if (!first) return null
    const ms = catFrames(first)!.avgMs!
    return ms < L07_TOO_FAST_MS ? '快得看不清' : ms >= L07_VISIBLE_MS ? '看得清' : null
  }
  if (id === g2u2L04.id) {
    const first = flightSummary(obs.frameRuns.find(r => (r.turns?.['蝴蝶'] ?? 0) > 0))
    if (!first) return null
    return first.closed ? '能回到起点' : '回不到起点'
  }
  if (id === g2u2L03.id) {
    const first = obs.beatRuns.find(r => r.finished && r.hits.some(h => h.target === L09_DRUM))
    if (!first) return null
    const said = `${beatSummary(first).dongs} 下`
    return g2u2L03.predict.options.includes(said) ? said : null
  }
  if (id === g2u2L02.id) {
    const first = obs.cycleRuns[0]
    if (!first) return null
    if (first.switches >= 3) return '一直换，直到按停止'
    return first.finished && !first.stopped ? '换 1 次就停' : null
  }
  return null
}

export function evaluateG2U2Lesson(id: string, obs: G2Observations): G2TaskState | null {
  if (id === g2u2L01.id) return evaluateG2U2L01(obs)
  if (id === g2u2L02.id) return evaluateG2U2L02(obs)
  if (id === g2u2L03.id) return evaluateG2U2L03(obs)
  if (id === g2u2L04.id) return evaluateG2U2L04(obs)
  return null
}

export const g2u2ScratchLessons: Record<string, G2Lesson> = {
  [g2u2L01.id]: g2u2L01,
  [g2u2L02.id]: g2u2L02,
  [g2u2L03.id]: g2u2L03,
  [g2u2L04.id]: g2u2L04,
}
